export function showPicoSupport(project,showDialog){
 const python=project.language==='micropython',native=python&&project.settings.picoPythonEngine==='rp2-native',riscv=project.settings.picoArchitecture==='riscv';
 const title=python?(native?'Pico · Native RP2 MicroPython':'Pico · MicroPython WASM'):'Pico · '+(riscv?'Hazard3 C':'ARM C');
 const body=native?'<p>Özgün RP2 ARM firmware profili; iki emüle CPU aynı SRAM’i kullanır. Normal <code>time.sleep</code> ve bu profilin <code>_thread</code> desteği kullanılır. ROM/firmware ayrıca indirilir. Genel Pico/Pico 2 CPU profili; W radyosu yürütülmez.</p>':python?'<p>MicroPython WASM yorumlayıcısı, devre adaptörüyle Pin, ADC, PWM ve desteklenen veri yolu/modüllerine bağlanır. Canlı etkileşim için döngüde <code>await js.cf.sleep(ms)</code> kullanın. Native RP2 portu ve <code>_thread</code> bu motorun parçası değildir.</p>':'<p>Tarayıcıda C17 derlenir ve gerçek '+(riscv?'Hazard3':'ARM')+' makine kodu emüle edilir. Ek .c/.h dosyalarını Dosya / kütüphane al ile ekleyin. SDK uyumluluk katmanı ve sınırlı CMake kaynak/hedef değerlendirmesi vardır; tam upstream SDK/CMake değildir.</p><p>Normal Derle → Çalıştır için paket veya ek uygulama gerekmez. İsteğe bağlı kaynak paketi yalnız uyumlu C/H dosyalarını ekler; JSON tek başına SDK sağlamaz.</p>';
 showDialog(title,body+'<p><a href="./pico-support.html" target="_blank">Güncel kapsam ve sınırlar</a> · <a href="./guide.html" target="_blank">Kullanım kılavuzu</a></p><details><summary>Teknik ayrıntılar</summary><p><a href="./notices/PICO-MODEL.md" target="_blank">Model/API kaydı</a> · <a href="./notices/PICO-BROWSER-CMAKE.md" target="_blank">CMake alt kümesi</a> · <a href="./notices/PICO-ROM-SOURCES.md" target="_blank">ROM kaynakları/lisans</a></p></details>');
}
